{
  "summary": "Anna is a premium soft-tech AI brand with muted pastel color, quiet futurism, restrained glassmorphism, and a calm digital companion feeling. The brand uses low-saturation elegance with misty atmospheres.",
  "keywords": ["premium soft tech", "quiet futurism", "muted pastel", "low-saturation elegance", "calm digital companion", "restrained glassmorphism"],
  "color_direction": "muted low-saturation pastel, misty atmosphere with soft glass accents",
  "primary_colors": [
    {"name": "Premium Mist White", "hex": "#F2F0F1", "role": "background"},
    {"name": "Muted Lavender Gray", "hex": "#DDD7E2", "role": "secondary surface"},
    {"name": "Muted Blush Pink", "hex": "#E8C7D0", "role": "emotional accent"}
  ],
  "auxiliary_colors": [
    {"name": "Pale Cool Mist Blue", "hex": "#D8E0E8", "role": "contrast accent"},
    {"name": "Deep Plum Charcoal", "hex": "#17151C", "role": "text & depth"}
  ],
  "color_rules": {
    "preferred": ["mist white + lavender gray base", "blush pink as accent only"],
    "avoid": ["neon on pastel", "high saturation color blocking", "candy pink + bright blue"]
  },
  "logo_rules": [
    "Do not generate, redraw, stretch, rotate, or recolor the Anna logo.",
    "Use fixed logo assets as a post-generation overlay for final brand visuals.",
    "Leave clear space around logo placement."
  ],
  "mascot_rules": [
    "Do not generate, redraw, or distort the Anna mascot.",
    "Use fixed mascot assets as a post-generation overlay.",
    "Can be placed as a secondary element with good spacing."
  ],
  "visual_style": {
    "tone": "premium muted pastel, quiet futuristic, high-end but approachable",
    "composition": "spacious composition with one core visual object and one to two supporting elements",
    "density": "low_to_medium",
    "background": "mist white, gray-lavender, soft blush ambient light, subtle glass surface"
  },
  "do": [
    "Use large whitespace.",
    "Use restrained glassmorphism and soft diffuse light.",
    "Generate background and hero visual separately from exact logo and mascot overlays.",
    "Vary layout between outputs to avoid copying one reference structure."
  ],
  "do_not": [
    "Do not copy reference image layout or business semantics.",
    "Do not use high saturation, neon glow, or dense UI boards.",
    "Do not ask the image model to freely create logo or mascot in final assets.",
    "Do not place too much text inside the image-generation step."
  ],
  "typography": {
    "headline": "Modern sans-serif, bold weight (700-800), clean geometric forms",
    "subheadline": "Regular or medium weight sans-serif, generous spacing",
    "body": "Minimal usage; if needed, regular sans-serif at small size"
  },
  "confidence": {
    "style": "85%",
    "color": "90%",
    "layout": "75%",
    "asset_rules": "95%"
  }
}

