      "negative_prompt": ["no neon", "no generated logo", "no distorted mascot", "no high saturation", "no dense text"],
      "execution_notes": ["Separate bg generation from asset overlay", "Logo and mascot are fixed assets", "Vary composition from references"]
    },
    "review_checklist": {
      "style": ["Color direction matches intent", "Visual tone aligns with brand", "Density appropriate for platform"],
      "color": ["Primary colors correct", "No banned color combos"],
      "assets": ["Logo policy defined", "Mascot policy defined", "Clear spacing rules"],
