    }
  }
}

{
  "visual": {
    "visual_id": "visual_1747735200",
    "platform": "LinkedIn",
    "user_request": "Make a LinkedIn poster about why enterprises need secure AI Agents",
    "prompt": "Create a LinkedIn visual for Anna brand. The visual should follow the brand's muted low-saturation pastel palette (Premium Mist White #F2F0F1, Muted Lavender Gray #DDD7E2, Muted Blush Pink #E8C7D0). Use a spacious single-hero composition with soft glassmorphism textures and subtle diffuse light. Low-to-medium information density. The background should have a misty atmosphere. NO logo or mascot in this step — they will be overlaid separately. Clean geometric forms, premium soft-tech aesthetic. Enterprise AI security theme.",
    "negative_instructions": [
      "no neon colors",
      "no high saturation",
      "no generated or approximated logo",
      "no distorted mascot",
      "no dense text blocks",
      "no copied reference layout",
      "no cluttered compositions"
    ],
    "compliance_explanation": "This visual follows the Anna Brand Visual Manual: muted low-saturation pastel palette, low-to-medium information density, restrained glassmorphism, soft diffuse light, and the fixed asset overlay policy for logo and mascot. It avoids explicitly banned behaviors like neon, high saturation, dense layouts, and freehand brand-asset generation.",
    "preview": {
      "headline": "Secure AI Agents, designed with trust.",
      "palette": ["#F2F0F1", "#DDD7E2", "#E8C7D0", "#D8E0E8", "#17151C"],
      "layout": "spacious hero visual with fixed asset overlay"
    }
  }
}
